using System;
using System.Collections;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
[InitializeOnLoad]public static class GridShiftV19UICapture {
 static GridShiftV19UICapture(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("GS19UI",false)){var go=new GameObject("Real finance save UI capture");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftV19UICaptureRunner>();}};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){if(!SessionState.GetBool("GS19UI",false))return;var directory="Docs/Validacao19/snapshots/primeira-entrega.json";GridShiftProfiles.RootOverride=Path.GetFullPath("Temp/Replay19Profiles");GridShiftProfiles.Login("v18@local.test","isolated",out _);if(!DeliverySaveStore.ReadAt(directory,out var data,out _))throw new Exception("Recorded real gameplay save unavailable");GridShiftProfiles.Activate(5,data.companyName);DeliverySaveStore.OverridePath=Path.GetFullPath("Temp/UICapture19-"+Guid.NewGuid().ToString("N")+"/slot.json");DeliverySaveStore.Pending=data;DeliverySaveStore.StartFresh=false;GridShiftCompany.SuppressIntro=true;Directory.CreateDirectory(GridShiftV19Film.Output);File.AppendAllText(GridShiftV19Film.Output+"/capturas.txt","UI SOURCE real completed-delivery save "+directory+" balance="+data.money+" completed="+data.orders.Count(o=>o.status==DeliveryStatus.Completed&&o.rewardPaid)+"\n");}
 public static void Batch(){if(!File.Exists("Docs/Validacao19/snapshots/primeira-entrega.json")){EditorApplication.Exit(2);return;}EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");SessionState.SetBool("GS19UI",true);GridShiftV19Film.Enabled=true;EditorApplication.isPlaying=true;}
}
public sealed class GridShiftV19UICaptureRunner:MonoBehaviour {
 IEnumerator Start(){while(DeliveryManager.Instance?.GetComponent<GridShiftActiveOperations>()?.Van==null||WorldSession.Instance.Busy)yield return null;yield return new WaitForSeconds(.5f);GridShiftOperationsUI.Instance.Close();var m=DeliveryManager.Instance;var p=InteractionFocus.PlayerFor(m);p.enabled=false;p.BlockControls(false);p.CameraTransform.localRotation=Quaternion.identity;var cfg=m.GetComponent<GridShiftActiveOperations>().Config;var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=cfg.depotPosition-cfg.depotRotation*Vector3.forward*6+Vector3.up*.12f;p.transform.rotation=cfg.depotRotation*Quaternion.Euler(0,90,0);Physics.SyncTransforms();cc.enabled=true;var tablet=p.GetComponent<PortableTablet>();if(!tablet.Open())throw new Exception("UI capture tablet did not open");yield return new WaitForSeconds(.8f);foreach(var shot in new[]{("Financeiro","12-tablet-financas-clean",5f),("Frota","13-frota-clean",4f),("Funcionários","14-funcionarios-clean",4f),("Missões","15-missoes-clean",4f),("Upgrades","16-upgrades-clean",4f)}){tablet.Operations.Show(shot.Item1);yield return new WaitForSeconds(.15f);yield return GridShiftV19Film.Record(shot.Item2,Camera.main,shot.Item3);}tablet.Close();yield return new WaitForSeconds(.8f);if(p.CameraTransform.Find("Hud")!=null&&!p.CameraTransform.Find("Hud").gameObject.activeSelf)throw new Exception("HUD did not restore after tablet");File.WriteAllText("Docs/Validacao19/tablet-restauracao.txt","PASS tablet hides local body layers 7/8 and 3D HUD geometry while open; restores HUD on close.\nRESULT SUCCESS\n");SessionState.SetBool("GS19UI",false);EditorApplication.Exit(0);}
}
